async fn test_payment_list_fetch_limits_endpoint_count_and_payload_bytes() {
    let setup = TestSetup::new().await;
    for (identifier, payload) in [("endpoint-1", "payload-1"), ("endpoint-2", "payload-2")] {
        set_payment_endpoint(
            &setup.session,
            &app_id(),
            PaymentEndpointIdentifier::new(identifier).unwrap(),
            PaymentEndpointPayload::new(payload),
        )
        .await
        .unwrap();
    }

    let list =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 2, 18)
            .await
            .unwrap();
    assert_eq!(list.payment_endpoints.len(), 2);

    let endpoint_limit =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 1, 18)
            .await;
    let endpoint_limit = endpoint_limit.unwrap_err();
    assert!(matches!(endpoint_limit, PaykitError::InvalidData { .. }));
    assert!(is_payment_list_limit_exceeded(&endpoint_limit));

    let payload_limit =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 2, 8)
            .await;
    let payload_limit = payload_limit.unwrap_err();
    assert!(matches!(payload_limit, PaykitError::InvalidData { .. }));
    assert!(is_payment_list_limit_exceeded(&payload_limit));

/// Amount of value in a payment flow, expressed as decimal text plus asset.
///
/// # Validation
///
/// [`PaymentAmount::new`] accepts a `value` consisting only of ASCII digits and
/// at most one decimal point, with at least one digit. Leading `+` and `-` signs
/// are rejected. Values such as `.5` and `10.` are accepted. The `asset` must be
/// non-empty and contain no control characters. Beyond these checks, Paykit
/// defines no range, precision, scale, normalization, or asset-registry policy.

impl PaymentAmount {
    /// Access the preserved decimal spelling.
    pub fn value(&self) -> &str {
        &self.value
    }
    /// Access the exact asset text.
    pub fn asset(&self) -> &str {
        &self.asset
    }

    /// Create a Payment Amount after validating its value and asset fields.
    pub fn new(value: impl Into<String>, asset: impl Into<String>) -> Result<Self> {
        Self::new_with_label(value.into(), asset.into(), "Payment Amount")
    }

    pub(crate) fn new_with_label(
        value: String,
        asset: String,
        label: &'static str,
    ) -> Result<Self> {
        let amount = Self { value, asset };
        amount.validate_with_label(label)?;
        Ok(amount)
    }

    pub(crate) fn validate_with_label(&self, label: &'static str) -> Result<()> {
        validate_decimal_text(&self.value, format_args!("{label}.value"))?;
        validate_asset_text(&self.asset, "Payment Amount asset")
    }

#[test]
fn payment_amount_accepts_decimal_value_and_asset() {
    let amount = PaymentAmount::new("10.00", "usd").unwrap();
    assert_eq!(amount.value, "10.00");
    assert_eq!(amount.asset, "usd");
}

#[test]
fn payment_amount_rejects_invalid_value() {
    let err = PaymentAmount::new("ten", "usd").unwrap_err();
    assert!(matches!(err, PaykitError::Validation(msg) if msg.contains("decimal string")));
}

impl PaymentReference {
    /// Create a Payment Reference after validating that the input is non-empty,
    /// bounded, and free of control characters.
    pub fn new(reference: impl Into<String>) -> Result<Self> {
        let reference = reference.into();
        if reference.is_empty() {
            return Err(PaykitError::Validation(
                "Payment Reference must not be empty".into(),
            ));
        }
        let char_count = reference.chars().count();
        if char_count > PAYMENT_REFERENCE_MAX_LEN {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not exceed {PAYMENT_REFERENCE_MAX_LEN} characters, got {char_count}"
            )));
        }
        if let Some((pos, ch)) = reference.char_indices().find(|&(_, ch)| ch.is_control()) {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not contain control character U+{:04X} at byte {pos}",
                ch as u32
            )));
        }
        Ok(Self(reference))
    }

