impl PaymentRequestTerms {
    /// Start constructing terms with their required amount, reference, and endpoints.
    ///
    /// Call [`PaymentRequestTermsBuilder::build`] to validate the complete terms.
    pub fn builder(
        amount: PaymentAmount,
        payment_reference: PaymentReference,
        accepted_payment_endpoint_identifiers: Vec<PaymentEndpointIdentifier>,
    ) -> PaymentRequestTermsBuilder {
        PaymentRequestTermsBuilder(Self {
            amount,
            payment_reference,
            accepted_payment_endpoint_identifiers,
            payment_endpoints: None,
            required_app_id: None,
            proposal_expires_at: None,
            recurrence: None,
            conversion: None,
            payment_deadline: None,
            metadata: JsonMap::new(),
        })
    }
}

impl PaymentRequestTermsBuilder {
    /// Bind payment to immutable Payment Endpoints owned by `required_app_id`.
    ///
    /// A supplied map must be nonempty, contain nonempty payloads, and use only
    /// accepted Payment Endpoint Identifiers. `required_app_id` must be set.
    /// `None` preserves endpoint discovery; `Some` forbids fallback outside the map.
    pub fn payment_endpoints(
        mut self,
        value: Option<HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>>,
    ) -> Self {
        self.0.payment_endpoints = value;
        self
    }
    /// Constrain payment to an endpoint owned by the specified payee App.
    pub fn required_app_id(mut self, value: Option<crate::PaykitAppId>) -> Self {
        self.0.required_app_id = value;
        self
    }

/// Validate the complete terms, including the non-empty endpoint list.
pub fn build(self) -> Result<PaymentRequestTerms> {
    self.0.validate()?;
    Ok(self.0)
}

impl PaymentRequest {
    pub(super) fn validate(&self) -> Result<()> {
        crate::validation::validate_outgoing_version_kind(
            self.version,
            self.kind,
            PrivateMessageKind::PaymentRequest,
            "Payment Request",
        )?;
        self.request.validate()
    }

    /// Construct a Payment Request proposal using protocol version 1.
    pub fn new(
        event_id: EventId,
        payment_request_id: PaymentRequestId,
        request: PaymentRequestTerms,
    ) -> Self {
        Self {
            version: 1,
            kind: PrivateMessageKind::PaymentRequest,
            event_id,
            payment_request_id,
            request,
        }
    }

/// Serialize a Payment Request protocol Event Message to canonical JSON.
pub fn serialize_payment_request_event(
    app_id: &PaykitAppId,
    event: &PaymentRequestEvent,
) -> Result<String> {
    match event {
        PaymentRequestEvent::Request(event) => serialize_payment_request_json(app_id, event),
        PaymentRequestEvent::Acceptance(event) => serialize_acceptance_json(app_id, event),
        PaymentRequestEvent::Rejection(event) => serialize_rejection_json(app_id, event),
        PaymentRequestEvent::Cancellation(event) => serialize_cancellation_json(app_id, event),
        PaymentRequestEvent::Proof(event) => serialize_payment_proof_json(app_id, event),
        PaymentRequestEvent::ConversionQuote(event) => {
            serialize_conversion_quote_json(app_id, event)
        }
    }
}

/// Parse a raw Private Application Message as a Payment Request protocol event.
///
/// Returns `None` when the message kind is not one of the Payment Request
/// protocol event kinds. Recognized but malformed Payment Request events return
/// `Some` with [`PaymentRequestEventMessage::is_valid`] set to `false`.
pub fn parse_payment_request_event_message(
    message: &PrivateApplicationMessage,
) -> Option<PaymentRequestEventMessage> {
    let kind = message.known_kind()?;
    let event = parse_event(kind, &message.raw_json)?.map_err(|err| err.to_string());
    let (app_id, event_id, payment_request_id) = parse_event_header(&message.raw_json);
    Some(PaymentRequestEventMessage {
        kind,
        app_id,
        event_id,
        payment_request_id,
        raw_json: message.raw_json.clone(),
        event,
    })
}

        self.app_id.as_ref()
    }

    /// Whether the recognized event message parsed successfully.
    pub fn is_valid(&self) -> bool {
        self.event.is_ok()
    }

    /// Access the parsed event when structural validation succeeded.
    pub fn parsed_event(&self) -> Option<&PaymentRequestEvent> {
        self.event.as_ref().ok()
    }

    /// Access the validation error when structural validation failed.
    pub fn validation_error(&self) -> Option<&str> {
        self.event.as_ref().err().map(String::as_str)
    }

    /// Access the Event ID.
    ///
    /// Returns `None` when the recognized message is malformed and the Event ID
    /// could not be parsed as a valid Event ID.
    pub fn event_id(&self) -> Option<&EventId> {
        self.event_id.as_ref()
    }

    /// Access the Payment Request ID shared by this lifecycle event.
    ///
    /// Returns `None` when the recognized message is malformed and the Payment
    /// Request ID could not be parsed as a valid Payment Request ID.
    pub fn payment_request_id(&self) -> Option<&PaymentRequestId> {
        self.payment_request_id.as_ref()
    }
}

/// Send a `paykit.payment_request` Event Message.
///
/// Payment Requests are payee-initiated; caller code must enforce the sender
/// role.
#[instrument(skip(link, event))]
pub async fn send_payment_request(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequest,
) -> Result<()> {
    let json = serialize_payment_request_json(app_id, event)
        .map_err(|err| map_error("send_payment_request", err))?;
    link.send_payment_request_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request", err))
}

/// Send a `paykit.payment_request_acceptance` Event Message.
///
/// Acceptances are payer-initiated; caller code must enforce the sender role.
#[instrument(skip(link, event))]
pub async fn send_payment_request_acceptance(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequestAcceptance,
) -> Result<()> {
    let json = serialize_acceptance_json(app_id, event)
        .map_err(|err| map_error("send_payment_request_acceptance", err))?;
    link.send_payment_request_acceptance_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request_acceptance", err))
}

/// One Private Application Message received from an Encrypted Link.
///
/// This is the low-level receive item for the Private Application Message stream.
/// It keeps the raw plaintext payload so callers can route and persist messages
/// themselves. If decrypted bytes are not UTF-8, `raw_json` contains a local
/// invalid-JSON marker with the bytes encoded as base64url. Higher layers should
/// treat that marker as malformed input, not as a Private Application Message.
#[derive(Clone, PartialEq, Eq)]
pub struct PrivateApplicationMessage {
    /// Private Application Message version from the JSON `version` field, when
    /// the field is present and can be represented as a `u8`.
    pub version: Option<u8>,
    /// Message kind string from the JSON `kind` field, when the field is a
    /// string.
    pub kind: Option<String>,
    /// App ID string from the JSON `app_id` field, when the field is a string.
    pub app_id: Option<String>,
    /// Raw plaintext received over the Encrypted Link.
    pub raw_json: String,
}

impl std::fmt::Debug for PrivateApplicationMessage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PrivateApplicationMessage")
            .field("version", &self.version)
            .field("kind", &self.kind)
            .field("app_id", &self.app_id)
            .field(
                "raw_json",
                &format_args!("<redacted:{} bytes>", self.raw_json.len()),
            )
            .finish()

